import re


class CsvError(Exception):
    def __init__(self, message, line, col):
        super().__init__("%s (line %d, col %d)" % (message, line, col))
        self.line = line
        self.col = col


_INT_RE = re.compile(r"-?[0-9]+")


def parse(text, dialect):
    delim = dialect.get("delimiter", ",")
    quote = dialect.get("quote", '"')
    escape = dialect.get("escape", None)
    skip_initial_space = dialect.get("skip_initial_space", False)
    comment = dialect.get("comment", None)
    skip_blank = dialect.get("skip_blank", True)
    strict = dialect.get("strict", True)
    header = dialect.get("header", False)
    fill = dialect.get("fill", None)
    null_values = dialect.get("null_values", [])
    infer_ints = dialect.get("infer_ints", False)
    trim = dialect.get("trim", False)

    if text.startswith("\ufeff"):
        text = text[1:]
    n = len(text)
    i = 0
    line = 1
    col = 1

    def adv():
        nonlocal i, line, col
        c = text[i]
        if c == "\r":
            line += 1
            col = 1
        elif c == "\n":
            if not (i > 0 and text[i - 1] == "\r"):
                line += 1
                col = 1
        else:
            col += 1
        i += 1

    def consume_break():
        if i < n and text[i] == "\r":
            adv()
            if i < n and text[i] == "\n":
                adv()
        elif i < n and text[i] == "\n":
            adv()

    def parse_field():
        # returns (string, is_quoted)
        if skip_initial_space:
            while i < n and text[i] == " ":
                adv()
        if quote is not None and i < n and text[i] == quote:
            open_line, open_col = line, col
            adv()
            buf = []
            while True:
                if i >= n:
                    raise CsvError("unterminated quoted field", open_line, open_col)
                c = text[i]
                if escape is not None and c == escape:
                    if i + 1 >= n:
                        raise CsvError("unterminated quoted field", open_line, open_col)
                    adv()
                    buf.append(text[i])
                    adv()
                elif c == quote:
                    if escape is None and i + 1 < n and text[i + 1] == quote:
                        buf.append(quote)
                        adv()
                        adv()
                    else:
                        adv()
                        break
                else:
                    buf.append(c)
                    adv()
            if i < n and text[i] != delim and text[i] not in "\r\n":
                if strict:
                    raise CsvError("unexpected character after closing quote", line, col)
                while i < n and text[i] != delim and text[i] not in "\r\n":
                    buf.append(text[i])
                    adv()
            return ("".join(buf), True)
        start = i
        while i < n and text[i] != delim and text[i] not in "\r\n":
            adv()
        return (text[start:i], False)

    records = []
    while i < n:
        c = text[i]
        if c in "\r\n":
            consume_break()
            if not skip_blank:
                records.append([("", False)])
            continue
        if comment is not None and c == comment:
            while i < n and text[i] not in "\r\n":
                adv()
            consume_break()
            continue
        fields = []
        while True:
            fields.append(parse_field())
            if i < n and text[i] == delim:
                adv()
                continue
            break
        consume_break()
        records.append(fields)

    def process(field):
        s, quoted = field
        if quoted:
            return s
        if trim:
            s = s.strip(" \t")
        if s in null_values:
            return None
        if infer_ints and _INT_RE.fullmatch(s):
            return int(s)
        return s

    if not header:
        return [[process(f) for f in rec] for rec in records]

    if not records:
        return []
    names = []
    counts = {}
    for idx, (s, _q) in enumerate(records[0]):
        name = s if s != "" else "col%d" % (idx + 1)
        k = counts.get(name, 0)
        counts[name] = k + 1
        if k >= 1:
            names.append("%s_%d" % (name, k + 1))
        else:
            names.append(name)

    result = []
    nn = len(names)
    for rec in records[1:]:
        vals = [process(f) for f in rec]
        d = {}
        for j, name in enumerate(names):
            d[name] = vals[j] if j < len(vals) else fill
        if len(vals) > nn:
            d["_extra"] = vals[nn:]
        result.append(d)
    return result
